arguments.file_text:
@using sv_713ce7f112f74081b7ce6e58b9c4ad7e.Models
@inject ISettingsService SettingsService

<section>
    <h4 class="section-heading">Profile</h4>
    <p class="text-muted mb-4">Manage your personal information and public profile.</p>

    @if (_loading)
    {
        <div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div></div>
    }
    else
    {
        <div class="row g-4">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="_displayName" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="_email" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="_bio"></textarea>
                </div>
            </div>

            <div class="col-md-4">
                <label class="form-label fw-semibold">Avatar Preview</label>
                <div class="avatar-preview-area">
                    @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                    {
                        <img src="@_avatarUrl" alt="Avatar" class="avatar-image" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">No avatar</div>
                    }
                </div>
                <div class="mt-2">
                    <label class="form-label small text-muted mb-1">Avatar URL</label>
                    <input type="url" class="form-control form-control-sm" @bind="_avatarUrl" />
                </div>
            </div>
        </div>

        <div class="d-flex gap-2 mt-4">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@_saving">
                Discard Changes
            </button>
        </div>

        @if (_toast is not null)
        {
            <div class="alert @(_toastIsError ? "alert-danger" : "alert-success") mt-3 mb-0 d-flex align-items-center" role="alert">
                <span>@_toast</span>
                <button type="button" class="btn-close ms-auto" @onclick="() => _toast = null"></button>
            </div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _toast;
    private bool _toastIsError;

    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    private UserProfile _savedProfile = null!;

    protected override async Task OnInitializedAsync()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile p)
    {
        _displayName = p.DisplayName;
        _email = p.Email;
        _bio = p.Bio;
        _avatarUrl = p.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _toast = null;
        try
        {
            var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(profile);
            _savedProfile = profile;
            _toast = "Profile saved successfully.";
            _toastIsError = false;
        }
        catch (Exception ex)
        {
            _toast = $"Failed to save profile: {ex.Message}";
            _toastIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        ApplyProfile(_savedProfile);
        _toast = null;
    }
}

.section-heading {
    margin-bottom: 0.25rem;
}

.avatar-preview-area {
    width: 128px;
    height: 128px;
    border: 2px dashed #ced4da;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    background: #f8f9fa;
}

.avatar-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    color: #adb5bd;
    font-size: 0.85rem;
}

@using sv_713ce7f112f74081b7ce6e58b9c4ad7e.Models
@inject ISettingsService SettingsService

<section>
    <h4 class="mb-1">Notifications</h4>
    <p class="text-muted mb-4">Choose how and when you want to be notified.</p>

    @if (_loading)
    {
        <div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div></div>
    }
    else
    {
        <div class="card mb-4">
            <div class="card-body">
                <h6 class="card-title mb-3">General</h6>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                    <label class="form-check-label" for="emailNotif">
                        <strong>Email Notifications</strong>
                        <br /><small class="text-muted">Receive notifications via email</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                    <label class="form-check-label" for="pushNotif">
                        <strong>Push Notifications</strong>
                        <br /><small class="text-muted">Receive browser push notifications</small>
                    </label>
                </div>

                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                    <label class="form-check-label" for="weeklyDigest">
                        <strong>Weekly Digest</strong>
                        <br /><small class="text-muted">Get a weekly summary of activity</small>
                    </label>
                </div>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-body">
                <h6 class="card-title mb-3">Muted Channels</h6>
                <p class="text-muted small">Uncheck channels you want to mute.</p>

                @if (_allChannels.Count == 0)
                {
                    <p class="text-muted fst-italic">No channels available.</p>
                }
                else
                {
                    @foreach (var channel in _allChannels)
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="ch-@channel"
                                   checked="@(!_mutedChannels.Contains(channel))"
                                   @onchange="e => ToggleMute(channel, e)" />
                            <label class="form-check-label" for="ch-@channel">@channel</label>
                        </div>
                    }
                }
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save Preferences
        </button>

        @if (_toast is not null)
        {
            <div class="alert @(_toastIsError ? "alert-danger" : "alert-success") mt-3 mb-0" role="alert">
                @_toast
                <button type="button" class="btn-close ms-auto float-end" @onclick="() => _toast = null"></button>
            </div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _toast;
    private bool _toastIsError;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();

    // Represents all known channels; the service provides the muted subset.
    private readonly List<string> _allChannels = ["general", "announcements", "engineering", "design", "random"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels ?? []);
        _loading = false;
    }

    private void ToggleMute(string channel, ChangeEventArgs e)
    {
        bool isActive = (bool)(e.Value ?? false);
        if (isActive)
            _mutedChannels.Remove(channel);
        else
            _mutedChannels.Add(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _toast = null;
        try
        {
            var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            _toast = "Notification preferences saved.";
            _toastIsError = false;
        }
        catch (Exception ex)
        {
            _toast = $"Failed to save: {ex.Message}";
            _toastIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }
}

@using sv_713ce7f112f74081b7ce6e58b9c4ad7e.Models
@inject ISettingsService SettingsService

<section>
    <h4 class="mb-1">Security</h4>
    <p class="text-muted mb-4">Manage your password, two-factor authentication, and active sessions.</p>

    @if (_loading)
    {
        <div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div></div>
    }
    else
    {
        @* --- Change Password Panel --- *@
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center cursor-pointer"
                 @onclick="() => _passwordExpanded = !_passwordExpanded"
                 style="cursor:pointer">
                <h6 class="mb-0">Change Password</h6>
                <span>@(_passwordExpanded ? "▲" : "▼")</span>
            </div>
            @if (_passwordExpanded)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" style="max-width:400px" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" style="max-width:400px" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" style="max-width:400px" @bind="_confirmPassword" />
                    </div>

                    <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @if (_changingPassword)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Update Password
                    </button>

                    @if (_passwordMessage is not null)
                    {
                        <div class="alert @(_passwordError ? "alert-danger" : "alert-success") mt-3 mb-0" role="alert">
                            @_passwordMessage
                        </div>
                    }
                </div>
            }
        </div>

        @* --- Two-Factor Authentication --- *@
        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" style="transform:scale(1.4)" />
                </div>
            </div>
        </div>

        @* --- Active Sessions --- *@
        <div class="card mb-4">
            <div class="card-body">
                <h6 class="card-title mb-3">Active Sessions</h6>

                @if (_sessions.Count == 0)
                {
                    <p class="text-muted fst-italic">No active sessions.</p>
                }
                else
                {
                    <div class="table-responsive">
                        <table class="table table-hover align-middle mb-0">
                            <thead class="table-light">
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th style="width:120px"></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td>
                                            @if (session != _sessions[0])
                                            {
                                                @if (_confirmRevokeId == session.Id)
                                                {
                                                    <div class="d-flex gap-1">
                                                        <button class="btn btn-danger btn-sm" @onclick="() => RevokeConfirmedAsync(session.Id)">
                                                            Confirm
                                                        </button>
                                                        <button class="btn btn-outline-secondary btn-sm" @onclick="() => _confirmRevokeId = null">
                                                            Cancel
                                                        </button>
                                                    </div>
                                                }
                                                else
                                                {
                                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => _confirmRevokeId = session.Id">
                                                        Revoke
                                                    </button>
                                                }
                                            }
                                            else
                                            {
                                                <span class="badge bg-primary">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
            </div>
