<section>
    <h4 class="mb-1">Security</h4>
    <p class="text-muted mb-4">Manage your password, two-factor authentication, and active sessions.</p>

    @if (_loading)
    {
        <div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div></div>
    }
    else
    {
        @* --- Change Password Panel --- *@
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center cursor-pointer"
                 @onclick="() => _passwordExpanded = !_passwordExpanded"
                 style="cursor:pointer">
                <h6 class="mb-0">Change Password</h6>
