                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" style="max-width:400px" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" style="max-width:400px" @bind="_confirmPassword" />
                    </div>

                    <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @if (_changingPassword)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Update Password
                    </button>

                    @if (_passwordMessage is not null)
                    {
                        <div class="alert @(_passwordError ? "alert-danger" : "alert-success") mt-3 mb-0" role="alert">
                            @_passwordMessage
                        </div>
                    }
                </div>
            }
        </div>

        @* --- Two-Factor Authentication --- *@
        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" style="transform:scale(1.4)" />
                </div>
            </div>
        </div>

        @* --- Active Sessions --- *@
        <div class="card mb-4">
            <div class="card-body">
                <h6 class="card-title mb-3">Active Sessions</h6>

                @if (_sessions.Count == 0)
                {
                    <p class="text-muted fst-italic">No active sessions.</p>
                }
                else
                {
                    <div class="table-responsive">
                        <table class="table table-hover align-middle mb-0">
                            <thead class="table-light">
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th style="width:120px"></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td>
                                            @if (session != _sessions[0])
                                            {
                                                @if (_confirmRevokeId == session.Id)
                                                {
                                                    <div class="d-flex gap-1">
                                                        <button class="btn btn-danger btn-sm" @onclick="() => RevokeConfirmedAsync(session.Id)">
                                                            Confirm
                                                        </button>
                                                        <button class="btn btn-outline-secondary btn-sm" @onclick="() => _confirmRevokeId = null">
                                                            Cancel
                                                        </button>
                                                    </div>
                                                }
                                                else
                                                {
                                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => _confirmRevokeId = session.Id">
                                                        Revoke
                                                    </button>
                                                }
                                            }
                                            else
                                            {
                                                <span class="badge bg-primary">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
            </div>
        </div>

        @if (_sessionMessage is not null)
        {
            <div class="alert alert-info mt-2" role="alert">
                @_sessionMessage
            </div>
        }
    }
</section>

@code {
    private bool _loading = true;

    // Password
    private bool _passwordExpanded;
    private bool _changingPassword;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordMessage;
    private bool _passwordError;

    // 2FA
    private bool _twoFactorEnabled;

    // Sessions
    private List<ActiveSession> _sessions = [];
    private string? _confirmRevokeId;
    private string? _sessionMessage;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _sessions = settings.Sessions?.ToList() ?? [];
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordMessage = null;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "New password cannot be empty.";
            _passwordError = true;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordMessage = "New password and confirmation do not match.";
            _passwordError = true;
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordMessage = "Password updated successfully.";
            _passwordError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordMessage = $"Error: {ex.Message}";
            _passwordError = true;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private async Task RevokeConfirmedAsync(string sessionId)
    {
        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            _sessions.RemoveAll(s => s.Id == sessionId);
            _sessionMessage = "Session revoked.";
        }
        catch (Exception ex)
        {
            _sessionMessage = $"Failed to revoke session: {ex.Message}";
        }
        finally
        {
            _confirmRevokeId = null;
        }
    }
}
