@using sv_713ce7f112f74081b7ce6e58b9c4ad7e.Models
@inject ISettingsService SettingsService

<section>
    <h4 class="section-heading">Profile</h4>
    <p class="text-muted mb-4">Manage your personal information and public profile.</p>

    @if (_loading)
    {
        <div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div></div>
    }
    else
    {
        <div class="row g-4">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="_displayName" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="_email" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="_bio"></textarea>
                </div>
            </div>

            <div class="col-md-4">
                <label class="form-label fw-semibold">Avatar Preview</label>
                <div class="avatar-preview-area">
                    @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                    {
                        <img src="@_avatarUrl" alt="Avatar" class="avatar-image" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">No avatar</div>
                    }
                </div>
                <div class="mt-2">
                    <label class="form-label small text-muted mb-1">Avatar URL</label>
                    <input type="url" class="form-control form-control-sm" @bind="_avatarUrl" />
                </div>
            </div>
        </div>

        <div class="d-flex gap-2 mt-4">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@_saving">
                Discard Changes
            </button>
        </div>

        @if (_toast is not null)
        {
            <div class="alert @(_toastIsError ? "alert-danger" : "alert-success") mt-3 mb-0 d-flex align-items-center" role="alert">
                <span>@_toast</span>
                <button type="button" class="btn-close ms-auto" @onclick="() => _toast = null"></button>
            </div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _toast;
    private bool _toastIsError;

    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    private UserProfile _savedProfile = null!;

    protected override async Task OnInitializedAsync()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile p)
    {
        _displayName = p.DisplayName;
        _email = p.Email;
        _bio = p.Bio;
        _avatarUrl = p.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _toast = null;
        try
        {
            var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(profile);
            _savedProfile = profile;
            _toast = "Profile saved successfully.";
            _toastIsError = false;
        }
        catch (Exception ex)
        {
            _toast = $"Failed to save profile: {ex.Message}";
            _toastIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        ApplyProfile(_savedProfile);
        _toast = null;
    }
}

