+@using sv_713ce7f112f74081b7ce6e58b9c4ad7e.Models
+@inject ISettingsService SettingsService
+
+<section>
+    <h4 class="mb-1">Appearance</h4>
+    <p class="text-muted mb-4">Customize how the application looks and feels.</p>
+
+    @if (_loading)
+    {
+        <div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div></div>
+    }
+    else
+    {
+        <div class="row g-4">
+            <div class="col-md-7">
+                @* Theme *@
+                <div class="card mb-4">
+                    <div class="card-body">
+                        <h6 class="card-title mb-3">Theme</h6>
+                        @foreach (var theme in _themes)
+                        {
+                            <div class="form-check form-check-inline">
+                                <input class="form-check-input" type="radio" name="theme"
+                                       id="theme-@theme" value="@theme"
+                                       checked="@(_theme == theme)"
+                                       @onchange="() => _theme = theme" />
+                                <label class="form-check-label" for="theme-@theme">@theme</label>
+                            </div>
+                        }
+                    </div>
+                </div>
+
+                @* Font Size *@
+                <div class="card mb-4">
+                    <div class="card-body">
+                        <h6 class="card-title mb-3">Font Size</h6>
+                        @foreach (var size in _fontSizes)
+                        {
+                            <div class="form-check form-check-inline">
+                                <input class="form-check-input" type="radio" name="fontSize"
+                                       id="fs-@size" value="@size"
+                                       checked="@(_fontSize == size)"
+                                       @onchange="() => _fontSize = size" />
+                                <label class="form-check-label" for="fs-@size">@size</label>
+                            </div>
+                        }
+                    </div>
+                </div>
+
+                @* Language *@
+                <div class="card mb-4">
+                    <div class="card-body">
+                        <h6 class="card-title mb-3">Language</h6>
+                        <select class="form-select" style="max-width:300px" @bind="_language">
+                            @foreach (var lang in _languages)
+                            {
+                                <option value="@lang.Key">@lang.Value</option>
+                            }
+                        </select>
+                    </div>
+                </div>
+
+                @* Compact Mode *@
+                <div class="card mb-4">
+                    <div class="card-body d-flex justify-content-between align-items-center">
+                        <div>
+                            <h6 class="mb-1">Compact Mode</h6>
+                            <small class="text-muted">Reduce padding and spacing throughout the UI</small>
+                        </div>
+                        <div class="form-check form-switch">
+                            <input class="form-check-input" type="checkbox" @bind="_compactMode" style="transform:scale(1.4)" />
+                        </div>
+                    </div>
+                </div>
+
+                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
+                    @if (_saving)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+                    }
+                    Save
+                </button>
+
+                @if (_toast is not null)
+                {
+                    <div class="alert @(_toastIsError ? "alert-danger" : "alert-success") mt-3 mb-0" role="alert">
+                        @_toast
+                        <button type="button" class="btn-close ms-auto float-end" @onclick="() => _toast = null"></button>
+                    </div>
+                }
+            </div>
+
+            @* Live Preview *@
+            <div class="col-md-5">
+                <div class="card sticky-top" style="top:1rem">
+                    <div class="card-header fw-semibold">Live Preview</div>
+                    <div class="card-body preview-body @PreviewThemeClass" style="@PreviewFontStyle @PreviewPaddingStyle">
+                        <h6 style="@PreviewFontStyle">Dashboard</h6>
+                        <p style="@PreviewFontStyle">
+                            This is a preview of how content will appear with your selected settings.
+                        </p>
+                        <div class="d-flex gap-2">
+                            <button class="btn btn-primary btn-sm">Action</button>
+                            <button class="btn btn-outline-secondary btn-sm">Cancel</button>
+                        </div>
+                        <hr />
+                        <small class="text-muted" style="@PreviewFontStyle">
+                            Theme: @_theme &middot; Font: @_fontSize &middot; Lang: @_language &middot;
+                            Compact: @(_compactMode ? "On" : "Off")
+                        </small>
+                    </div>
+                </div>
+            </div>
+        </div>
+    }
+</section>
+
+@code {
+    private bool _loading = true;
+    private bool _saving;
+    private string? _toast;
+    private bool _toastIsError;
+
+    private string _theme = "Light";
+    private string _fontSize = "Medium";
+    private string _language = "en";
+    private bool _compactMode;
+
+    private static readonly string[] _themes = ["Light", "Dark", "System"];
+    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
+    private static readonly Dictionary<string, string> _languages = new()
+    {
+        ["en"] = "English",
+        ["es"] = "Español",
+        ["fr"] = "Français",
+        ["de"] = "Deutsch",
+        ["ja"] = "日本語",
+    };
+
+    private string PreviewThemeClass => _theme switch
+    {
+        "Dark" => "preview-dark",
+        _ => "preview-light"
+    };
+
+    private string PreviewFontStyle => _fontSize switch
+    {
+        "Small" => "font-size:0.85rem;",
+        "Large" => "font-size:1.15rem;",
+        _ => "font-size:1rem;"
+    };
+
+    private string PreviewPaddingStyle => _compactMode ? "padding:0.5rem;" : "padding:1.25rem;";
+
+    protected override async Task OnInitializedAsync()
+    {
+        var settings = await SettingsService.GetAppearanceAsync();
+        _theme = settings.Theme;
+        _fontSize = settings.FontSize;
+        _language = settings.Language;
+        _compactMode = settings.CompactMode;
+        _loading = false;
+    }
+
+    private async Task SaveAsync()
+    {
+        _saving = true;
+        _toast = null;
+        try
+        {
+            await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
+            _toast = "Appearance settings saved.";
+            _toastIsError = false;
+        }
+        catch (Exception ex)
+        {
+            _toast = $"Failed to save: {ex.Message}";
+            _toastIsError = true;
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

